function echoLetter(k: number): string {
  let p = k - 1, shifts = 0;
  while (p > 0) {
    let half = 1;
    while (half * 2 <= p) half *= 2; // largest power of two ≤ p
    p -= half;
    shifts++;
  }
  return String.fromCharCode(97 + (shifts % 26));
}

